const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Northern and Southern Taiwan regions
  const northernTaiwan = ee.Geometry.Polygon([
    [[120.0, 25.5], [122.0, 25.5], [122.0, 24.5], [120.0, 24.5], [120.0, 25.5]]
  ]);

  const southernTaiwan = ee.Geometry.Polygon([
    [[120.0, 23.5], [121.0, 23.5], [121.0, 22.0], [120.0, 22.0], [120.0, 23.5]]
  ]);

  // 2. Get TRMM precipitation data for August 3-9, 2009
  const startDate = '2009-08-03';
  const endDate = '2009-08-10';

  const trmm = ee.ImageCollection('TRMM/3B42')
    .filterDate(startDate, endDate);

  const collectionSize = trmm.size().getInfo();
  console.log(`TRMM Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No TRMM data available for the specified period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Calculate total rainfall for each region
  const totalRainfall = trmm.select('precipitation').sum();

  // Northern Taiwan rainfall
  const northStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northernTaiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const northCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northernTaiwan,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Southern Taiwan rainfall
  const southStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernTaiwan,
    scale: 5000,
    maxPixels: 1e9
  });

  const southCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southernTaiwan,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Northern Taiwan valid pixels: ${northCount}`);
  console.log(`Southern Taiwan valid pixels: ${southCount}`);

  if (northCount === 0 || southCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  const northRainfall = northStats.get('precipitation').getInfo();
  const southRainfall = southStats.get('precipitation').getInfo();

  console.log(`Northern Taiwan avg rainfall (mm): ${northRainfall !== null ? northRainfall.toFixed(2) : 'null'}`);
  console.log(`Southern Taiwan avg rainfall (mm): ${southRainfall !== null ? southRainfall.toFixed(2) : 'null'}`);

  if (northRainfall === null || southRainfall === null || 
      isNaN(northRainfall) || isNaN(southRainfall)) {
    console.log('Calculation returned invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Compare rainfall
  if (southRainfall > northRainfall) {
    console.log(`Southern Taiwan (${southRainfall.toFixed(2)} mm) > Northern Taiwan (${northRainfall.toFixed(2)} mm)`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Southern Taiwan (${southRainfall.toFixed(2)} mm) <= Northern Taiwan (${northRainfall.toFixed(2)} mm)`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
